import { useEffect } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { Link } from 'react-router-dom'
import { Table, Button, Container, Alert } from 'react-bootstrap'
import { listProducts, deleteProduct, createProduct } from '../actions/productActions'

const ProductListScreen = () => {
  const dispatch = useDispatch()
  const productList = useSelector(state => state.productList)
  const { loading, error, products } = productList
  const productDelete = useSelector(state => state.productDelete)
  const { success: successDelete } = productDelete
  const productCreate = useSelector(state => state.productCreate)
  const { success: successCreate, product: createdProduct } = productCreate

  useEffect(() => {
    dispatch(listProducts())
    if (successCreate) {
      dispatch({ type: 'PRODUCT_CREATE_RESET' })
      // redirecionar para editar o novo produto
      window.location.href = `/admin/product/${createdProduct._id}/edit`
    }
  }, [dispatch, successDelete, successCreate, createdProduct])

  const deleteHandler = (id) => {
    if (window.confirm('Tem certeza?')) dispatch(deleteProduct(id))
  }

  const createProductHandler = () => {
    dispatch(createProduct())
  }

  return (
    <Container className="py-4">
      <Table striped bordered hover responsive className="mt-3">
  <thead>
    <tr>
      <th>ID</th>
      <th>Nome</th>
      <th>Email</th>
      <th>Admin</th>
      <th>Ações</th>
    </tr>
  </thead>
  <tbody>
    {products.map(user => (
      <tr key={user._id}>
        <td>{user._id}</td>
        <td>{user.name}</td>
        <td>{user.email}</td>
        <td>{user.isAdmin ? 'Sim' : 'Não'}</td>
        <td>
          <Button variant="light" size="sm">Editar</Button>{' '}
          <Button variant="danger" size="sm">Excluir</Button>
        </td>
      </tr>
    ))}
  </tbody>
</Table>
     
    </Container>
  )
}

export default ProductListScreen
